// FILE: frontend/src/Tools.js (NEW FILE)
//
// --- VERSION 1.8.0 ---
// - This is a new page for housing administrative and diagnostic tools.
// - It features an interactive slider to test and apply different "fuzziness"
//   levels for the trip grouping algorithm.
// -----------------------------

import React, { useState, useCallback } from 'react';
import axios from 'axios';

function Tools() {
	const [sensitivity, setSensitivity] = useState(3);
	const [preview, setPreview] = useState(null);
	const [isLoading, setIsLoading] = useState(false);
	const [applyStatus, setApplyStatus] = useState('');

	const handlePreview = useCallback(async () => {
		setIsLoading(true);
		try {
			const response = await axios.post('http://localhost:5001/api/trip-groups/preview', { sensitivity });
			setPreview(response.data);
		} catch (error) {
			console.error("Error fetching preview:", error);
			setPreview({ error: "Could not fetch preview." });
		}
		setIsLoading(false);
	}, [sensitivity]);

	const handleApply = async () => {
		setIsLoading(true);
		setApplyStatus('Applying new grouping... This may take a moment.');
		try {
			// This is a placeholder for a dedicated apply endpoint. For now,
			// we'll just tell the user to run the script manually.
			// In a future version, this could trigger the script on the server.
			setApplyStatus('To apply, please run `python backend/group_trips.py` from your terminal.');
		} catch (error) {
			setApplyStatus('An error occurred.');
		}
		setIsLoading(false);
	};

	return (
		<div className="bg-gray-800 rounded-lg shadow-xl p-6">
			<h2 className="text-2xl font-bold mb-4 text-cyan-400">Diagnostic Tools</h2>

			<div className="border-t border-gray-700 pt-4">
				<h3 className="text-xl font-semibold">Trip Grouping Sensitivity</h3>
				<p className="text-gray-400 mt-1 mb-4">
					Adjust the "fuzziness" for automatic trip grouping. A higher number is more strict (less fuzzy). The default is 3.
				</p>
				<div className="flex items-center space-x-4">
					<input
						type="range"
						min="2"
						max="5"
						step="1"
						value={sensitivity}
						onChange={(e) => setSensitivity(parseInt(e.target.value))}
						className="w-64"
					/>
					<span className="font-mono text-lg">{sensitivity}</span>
					<button onClick={handlePreview} disabled={isLoading} className="bg-cyan-600 hover:bg-cyan-700 px-4 py-2 rounded-md disabled:opacity-50">
						{isLoading ? 'Loading...' : 'Preview'}
					</button>
					<button onClick={handleApply} disabled={isLoading} className="bg-green-600 hover:bg-green-700 px-4 py-2 rounded-md disabled:opacity-50">
						Apply
					</button>
				</div>
				{preview && (
					<div className="mt-4 p-4 bg-gray-700/50 rounded-md">
						<h4 className="font-bold">Preview Results:</h4>
						{preview.error ? <p className="text-red-400">{preview.error}</p> : (
							<p>With sensitivity set to {sensitivity}, the script would create approximately <span className="font-bold text-cyan-400">{preview.group_count}</span> groups, containing a total of <span className="font-bold text-cyan-400">{preview.total_trips_grouped}</span> recurring trips.</p>
						)}
					</div>
				)}
				 {applyStatus && <p className="mt-4 text-yellow-400">{applyStatus}</p>}
			</div>
		</div>
	);
}

export default Tools;
